<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><section class="section"><p>REPOSTERÍA MISVES</p><h1>Catálogo</h1><div class="grid"><?php foreach ($productos as $producto): ?><article class="card"><?php if (!empty($producto['imagen'])): ?><img src="<?= base_url('uploads/productos/' . esc($producto['imagen'])) ?>" alt="<?= esc($producto['nombre']) ?>"><?php endif; ?><h3><?= esc($producto['nombre']) ?></h3><p><?= esc($producto['descripcion'] ?? '') ?></p><div class="price">$<?= number_format((float) $producto['precio'], 0, ',', '.') ?></div></article><?php endforeach; ?></div></section><?= $this->endSection() ?>
